B.d7z=new A.q("id",B.D,"This node's handle \u2014 required for the mapSetLayerVisible / mapSetFilter / mapSetPaint runtime actions to target it (an id-less glmap still renders, just not runtime-controllable).",B.f,null)
B.cZ7=new A.q("table",B.at,"Marker source table (optional when tiles/geojsonSources is set).",B.f,null)
