B.d4H=new A.q("liveFormat",B.V,"Live formatting: render Markdown styling (bold / italic / headings / code / strikethrough) in the editor as you type, so the editor IS the preview. Off by default; Docs opts in.",B.f,null)
B.cS7=new A.q("dense",B.V,"Compact inline field: no outer padding, starts one line tall, body-medium text \u2014 a quiet field for compose cards, not a big box.",B.f,null)
